SELECT * FROM (
  WITH execution_counts AS (
    SELECT ordersmark, COUNT(*) as exec_count FROM orderexecutions GROUP BY ordersmark
  ),
  total_count AS (
    SELECT SUM(exec_count) as total_exec FROM execution_counts
  ),
  with_share AS (
    SELECT ec.ordersmark, ec.exec_count, CAST(ec.exec_count AS REAL) / CAST(tc.total_exec AS REAL) as share
    FROM execution_counts ec CROSS JOIN total_count tc
  ),
  avg_share AS (
    SELECT AVG(share) as avg_share_val FROM with_share
  )
  SELECT ws.ordersmark, ws.exec_count, ws.share, ws.share - av.avg_share_val as share_minus_avg
  FROM with_share ws CROSS JOIN avg_share av
  ORDER BY share_minus_avg DESC
  LIMIT 10
) ORDER BY CASE WHEN ordersmark IS NULL THEN 1 ELSE 0 END, share_minus_avg DESC;

